  it("Keeps existing vary values", async () => {
    t.app.all("/cors/**", (event) => {
      event.res.headers.set("vary", "origin");
      return serveStatic(event, {
        getContents: (id) => `asset:${id}`,
        getMeta: (id) => ({ type: "text/plain", path: id }),
        encodings: { gzip: ".gz" },
      });
    });
    const res = await t.fetch("/cors/test.png", {
      headers: { "accept-encoding": "gzip" },
    });
    expect(res.headers.get("vary")).toBe("origin, accept-encoding");
  });

  it("Sets vary when no encoding is accepted", async () => {
    // Explicit `identity`: node's fetch adds `accept-encoding: gzip, deflate` when unset.
    const res = await t.fetch("/test.png", {
      headers: { "accept-encoding": "identity" },
    });
    expect(await res.text()).toBe("asset:/test.png");
    expect(res.headers.get("vary")).toBe("accept-encoding");
  });

  it("Does not set vary without configured encodings", async () => {
    t.app.all("/plain/**", (event) => {
      return serveStatic(event, {
        getContents: (id) => `asset:${id}`,
        getMeta: (id) => ({ type: "text/plain", path: id }),
      });
    });
    const res = await t.fetch("/plain/test.png", {
      headers: { "accept-encoding": "gzip" },
    });
    expect(res.headers.get("vary")).toBeNull();
  });

  it("Does not duplicate vary values", async () => {
    for (const [i, vary] of ["Accept-Encoding", "origin,accept-encoding", "*"].entries()) {
      t.app.all(`/dedupe${i}/**`, (event) => {
        event.res.headers.set("vary", vary);
        return serveStatic(event, {
          getContents: (id) => `asset:${id}`,
          getMeta: (id) => ({ type: "text/plain", path: id }),
          encodings: { gzip: ".gz" },
        });
      });
      const res = await t.fetch(`/dedupe${i}/test.png`, {
        headers: { "accept-encoding": "gzip" },
      });
      expect(res.headers.get("vary")).toBe(vary);
    }
  });

  it("Matches encodings with q-values and any case", async () => {
    for (const [acceptEncoding, expected] of [
      ["gzip;q=1.0", "asset:/test.png.gz"],
      ["GZIP", "asset:/test.png.gz"],
      ["br ; q=1", "asset:/test.png.br"],
      // Preferred by weight, not by header order.
      ["gzip;q=0.5, br;q=0.8", "asset:/test.png.br"],
      // Equal weights keep header order.
      ["br, gzip", "asset:/test.png.br"],
      // `q=0` means "not acceptable".
      ["gzip;q=0, br;q=0.000", "asset:/test.png"],
      ["gzip;q=0", "asset:/test.png"],
      // A coding with an unparsable weight is dropped (identity is always safe).
      ["gzip;q=0invalid, br;q=0.5", "asset:/test.png.br"],
      ["gzip;q=0.0001", "asset:/test.png"],
      ["gzip;q=-1", "asset:/test.png"],
      ['gzip;q="0"', "asset:/test.png"],
      ["br;q=0.001, gzip;q=0.0010", "asset:/test.png.br"],
      // `x-gzip` is an alias of `gzip`.
      ["X-GZIP", "asset:/test.png.gz"],
      // `*` matches any coding not listed explicitly.
      ["*", "asset:/test.png.gz"],
      ["gzip;q=0, *", "asset:/test.png.br"],
      ["br;q=0.5, *;q=0.8", "asset:/test.png.gz"],
      ["*;q=0", "asset:/test.png"],
      // Explicitly listed codings win ties with `*` matches.
      ["*, br", "asset:/test.png.br"],
      // The first occurrence of a coding wins.
      ["gzip;q=0, gzip", "asset:/test.png"],
    ]) {
      const res = await t.fetch("/test.png", {
        headers: { "accept-encoding": acceptEncoding! },
      });
      expect(await res.text(), acceptEncoding).toBe(expected);
    }
  });

  it("Ignores inherited object keys in accept-encoding", async () => {
    const res = await t.fetch("/test.png", {
      headers: { "accept-encoding": "constructor, __proto__, toString" },
    });
    expect(await res.text()).toBe("asset:/test.png");
  });

  it("Normalizes configured encoding names", async () => {
    t.app.all("/aliases/**", (event) => {
      return serveStatic(event, {
        getContents: (id) => `asset:${id}`,
        getMeta: (id) => ({ type: "text/plain", path: id }),
        encodings: { GZIP: ".gz", "x-compress": ".Z" },
      });
    });
    for (const [acceptEncoding, expected] of [
      ["gzip", "asset:/aliases/test.png.gz"],
      ["compress", "asset:/aliases/test.png.Z"],
      ["x-compress", "asset:/aliases/test.png.Z"],
    ]) {
      const res = await t.fetch("/aliases/test.png", {
        headers: { "accept-encoding": acceptEncoding! },
      });
      expect(await res.text(), acceptEncoding).toBe(expected);
    }
  });

  it("Handles cache (if-none-match)", async () => {
    const res = await t.fetch("/test.png", {
      headers: { "if-none-match": "w/123" },
    });
    expect(res.headers.get("vary")).toBe("accept-encoding");
    expect(res.headers.get("etag")).toBe(expectedHeaders.etag);
    expect(res.status).toEqual(304);
    expect(await res.text()).toBe("");
  });

  it("Handles cache (if-modified-since)", async () => {
    const res = await t.fetch("/test.png", {
      headers: {
        "if-modified-since": new Date(1_700_000_000_001).toUTCString(),
      },
    });
    expect(res.status).toEqual(304);
    expect(await res.text()).toBe("");
  });

  it("Returns 404 if not found", async () => {
    const res = await t.fetch("/404/test.png");
    expect(res.status).toEqual(404);

    const headRes = await t.fetch("/404/test.png", { method: "HEAD" });
    expect(headRes.status).toEqual(404);
  });

  it("Handles cache (if-modified-since) for sub-second mtime", async () => {
    // mtime with millisecond precision. The `last-modified` header the server
    // emits is truncated to whole seconds (HTTP-date granularity), so a client
    // echoing that exact value in `if-modified-since` must still get a 304.
    const subSecondOptions: ServeStaticOptions = {
      getContents: vi.fn((id) => `asset:${id}`),
      getMeta: vi.fn((id) => ({
        type: "text/plain",
        mtime: 1_700_000_000_500, // 500ms past the whole second
        path: id,
        size: `asset:${id}`.length,
      })),
    };
    t.app.all("/subsec/**", (event) => serveStatic(event, subSecondOptions));

    // The exact value the server reports in `last-modified`.
    const lastModified = new Date(1_700_000_000_500).toUTCString();
    const res = await t.fetch("/subsec/test.png", {
      headers: { "if-modified-since": lastModified },
    });
    expect(res.status).toEqual(304);
    expect(await res.text()).toBe("");
  });

  it("Returns 405 if other methods used", async () => {
    const res = await t.fetch("/test.png", { method: "POST" });
    expect(res.status).toEqual(405);
  });

  it("Prevents path traversal via encoded dot segments", async () => {
    const res = await t.fetch("/%2e%2e/%2e%2e/etc/passwd");
    expect(res.status).toEqual(200);
    const text = await res.text();
    // After resolving dot segments, `/../../../etc/passwd` becomes `/etc/passwd`
    // The id must NOT contain `..` traversal sequences
    expect(text).not.toContain("..");
    expect(text).toMatch(/^asset:\/etc\/passwd/);
  });

  it("blocks path traversal attempts", async () => {
    const blocked = [
      "/../etc/passwd",
      "/%2e%2e/",
      "/%2E%2E/",
      "/assets/../../etc/passwd",
      "/assets/..",
      "/..\\etc\\passwd",
      "/..%5c..%5cetc%5cpasswd",
      "/..%2f..%2fetc%2fpasswd",
      "/..",
    ];
    for (const path of blocked) {
      const res = await t.fetch(path);
      const text = await res.text();
      // No bare `..` *segment*. Asserted on segment boundaries rather than as a
      // substring: an encoded separator stays encoded, so `/..%5c..%5cetc` (like
      // its `%2f` sibling) reaches the backend as one opaque segment whose text
      // begins with `..` but which has no boundary for a `..` to traverse across.
      // Decoding it into a real `/` is what this test exists to prevent.
      expect(text).not.toMatch(/(^|[\\/])\.\.([\\/]|$)/);
    }
  });

  it("does not pass double-encoded dot segments as traversal to backend", async () => {
    const res = await t.fetch("/%252e%252e/%252e%252e/etc/passwd");
    const text = await res.text();
    // After first decode: %2e%2e/%2e%2e/etc/passwd
    // Backend must NOT see %2e%2e which could be resolved as .. by downstream
    expect(text).not.toContain("%2e%2e");
    expect(text).not.toContain("%2E%2E");
  });

  it("does not reintroduce a backslash separator when decoding the id", async () => {
    // A double-encoded backslash traversal exercises the final `decodeURI`:
    // `%255c` survives `resolveDotSegments` (a single `%5c` is decoded to `\`
    // and normalized away one layer earlier), and the decode must collapse it
    // to a *literal* `%5c` — never a raw `\`. So the whole thing stays one
    // opaque segment: the `..` never becomes a bare path segment, and no new
    // separator boundary is introduced.
    const res = await t.fetch("/..%255c..%255cetc%255cpasswd");
    const text = await res.text();
    expect(text).not.toContain("\\"); // no raw backslash separator
    expect(text).toContain("%5c"); // stayed literal, not decoded to `\`
    // no bare `..` segment — boundaries include `\` so a decoded backslash
    // separator would be caught too, not only a `/`.
    expect(text).not.toMatch(/(^|[\\/])\.\.([\\/]|$)/);
  });

  it("keeps a single-encoded backslash opaque in the id", async () => {
    // `decodeURI` decodes `%5c` (not RFC 3986 reserved) to a raw `\`, which
    // `resolveDotSegments` then normalizes to `/`. That would hand the backend a
    // segment boundary that never existed for routing: `event.url.pathname` keeps
    // `%5c` encoded, so rou3 — and every `use(route, ...)` guard — sees one opaque
    // segment. The id must keep the same shape as what matched.
    const res = await t.fetch("/foo%5cbar.txt");
    const text = await res.text();
    expect(text).not.toContain("\\"); // never a raw backslash
    expect(text).not.toContain("/foo/bar.txt"); // and never a real boundary
    expect(text).toContain("%5c");
  });

  it("does not let an encoded backslash skip a pathname-scoped guard", async () => {
    // The desync in full: a `use("/private/**")` guard is matched against
    // `event.url.pathname` (`/private%5csecret.txt` — one segment, no match),
    // while the id must not resolve to the guarded `/private/secret.txt`.
    let guarded = false;
    const app = new H3()
      .use("/private/**", () => {
        guarded = true;
        return new Response("denied", { status: 401 });
      })
      .all("/**", (event) =>
        serveStatic(event, {
          getMeta: (id) => (id === "/private/secret.txt" ? { size: 6 } : undefined),
          getContents: () => "SECRET",
        }),
      );

    // Sanity: the guard does cover the canonical spelling.
    expect((await app.request("/private/secret.txt")).status).toBe(401);
    expect(guarded).toBe(true);

    const res = await app.request("/private%5csecret.txt");
    expect(res.status).toBe(404); // not 200 "SECRET"
    expect(await res.text()).not.toContain("SECRET");
  });

  it("decodes an encoded separator for the on-disk lookup", async () => {
    // serveStatic resolves `.`/`..` traversal first, then decodes once more, so
    // the id reaches the backend fully decoded — matching `sirv`/`serve-static`
    // and letting a filesystem-backed `getContents` skip self-decoding.
    // `/files/a%252fb` → id `a%2fb` (the encoded slash stays a literal `%2f`
    // segment, so no traversal is reintroduced).
    const res = await t.fetch("/files/a%252fb");
    expect(res.status).toEqual(200);
    const text = await res.text();
    expect(text).toContain("a%2fb");
    expect(text).not.toContain("a%252fb");
  });

  it("decodes a literal `%` in a filename for the on-disk lookup", async () => {
    // A file whose name contains a literal `%` (`50%.png`) is requested as
    // `/50%25.png`. The event layer preserves `%25`, then serveStatic decodes it
    // once more so the id reaches the backend as `/50%.png` — the on-disk name —
    // aligning with `sirv`/`serve-static` instead of forcing self-decoding.
    const res = await t.fetch("/50%25.png");
    expect(res.status).toEqual(200);
    const text = await res.text();
    expect(text).toContain("/50%.png");
    expect(text).not.toContain("/50%25.png");
  });

  it("allows legitimate paths with dots", async () => {
    const allowed = [
      "/_...grid_123.js",
      "/file..name.js",
      "/.hidden",
      "/assets/file.txt",
      "/...test/file.js",
    ];
    for (const path of allowed) {
      const res = await t.fetch(path);
      expect(res.status).toEqual(200);
      const text = await res.text();
      expect(text).toContain("asset:");
    }
  });
});

describeMatrix("serve static with fallthrough", (t, { it, expect }) => {
  beforeEach(() => {
    const serveStaticOptions = {
      getContents: vi.fn((id) => {
        return id.includes("404") || id.includes("fallthrough") ? undefined : `asset:${id}`;
      }),
      getMeta: vi.fn((id) =>
        id.includes("404") || id.includes("fallthrough")
          ? undefined
          : {
              type: "text/plain",
              encoding: "utf8",
              etag: "w/123",
              mtime: 1_700_000_000_000,
              path: id,
              size: `asset:${id}`.length,
            },
      ),
      indexNames: ["/index.html"],
      encodings: { gzip: ".gz", br: ".br" },
      fallthrough: true,
    } satisfies ServeStaticOptions;

    t.app.use((event) => {
      return serveStatic(event, serveStaticOptions);
    });

    t.app.use((event) => {
      if (event.path.includes("404")) {
        event.res.status = 404;
      }
      return { fallthroughTest: "passing" };
    });
  });

  const expectedHeaders = {
    "content-type": "text/plain",
    etag: "w/123",
    "content-encoding": "utf8",
    "last-modified": new Date(1_700_000_000_000).toUTCString(),
    vary: "accept-encoding",
  };

  it("Can serve asset (GET)", async () => {
    const res = await t.fetch("/test.png", {
      headers: {
        "if-none-match": "w/456",
        "if-modified-since": new Date(1_700_000_000_000 - 1).toUTCString(),
        "accept-encoding": "gzip, br",
      },
    });

    expect(res.status).toEqual(200);
    expect(await res.text()).toBe("asset:/test.png.gz");
    expect(Object.fromEntries(res.headers)).toMatchObject(expectedHeaders);
    expect(res.headers.get("content-length")).toBe("18");
  });

  it("Can serve asset (HEAD)", async () => {
    const headRes = await t.fetch("/test.png", {
      method: "HEAD",
      headers: {
        "if-none-match": "w/456",
        "if-modified-since": new Date(1_700_000_000_000 - 1).toUTCString(),
        "accept-encoding": "gzip, br",
      },
    });

    expect(headRes.status).toEqual(200);
    expect(await headRes.text()).toBe("");
    expect(Object.fromEntries(headRes.headers)).toMatchObject(expectedHeaders);
    expect(headRes.headers.get("content-length")).toBe("18");
  });

  it("Handles cache (if-none-match)", async () => {
    const res = await t.fetch("/test.png", {
      headers: { "if-none-match": "w/123" },
    });
    expect(res.headers.get("etag")).toBe(expectedHeaders.etag);
    expect(res.status).toEqual(304);
    expect(await res.text()).toBe("");
  });

  it("Handles cache (if-modified-since)", async () => {
    const res = await t.fetch("/test.png", {
      headers: {
        "if-modified-since": new Date(1_700_000_000_001).toUTCString(),
      },
    });
    expect(res.status).toEqual(304);
    expect(await res.text()).toBe("");
  });

  it("Returns 404 if not found", async () => {
    const res = await t.fetch("/404/test.png");
    expect(res.status).toEqual(404);

    const headRes = await t.fetch("/404/test.png", { method: "HEAD" });
    expect(headRes.status).toEqual(404);
  });

  it("ignores if-modified-since when a non-matching if-none-match is present (RFC 9110 §13.1.3, #1454)", async () => {
    // If-None-Match takes precedence: it does not match, so a fresh 200 must be
    // returned even though If-Modified-Since alone would have produced a 304.
    const res = await t.fetch("/test.png", {
      headers: {
        "if-none-match": "w/999",
        "if-modified-since": new Date(1_700_000_000_001).toUTCString(),
      },
    });
    expect(res.status).toEqual(200);
    expect(await res.text()).toContain("asset:/test.png");
  });

  it("Falls through to the next handler", async () => {
    const res = await t.fetch("/fallthrough/test.png");
    expect(res.status).toEqual(200);
    expect(await res.json()).toEqual({ fallthroughTest: "passing" });
  });

  it("Does not leak vary to the next handler", async () => {
    const res = await t.fetch("/fallthrough/test.png", {
      headers: { "accept-encoding": "gzip" },
    });
    expect(await res.json()).toEqual({ fallthroughTest: "passing" });
    expect(res.headers.get("vary")).toBeNull();
  });
});

describeMatrix("serve static MIME types", (t, { it, expect }) => {
  beforeEach(() => {
    const serveStaticOptions: ServeStaticOptions = {
      getContents: vi.fn((id) => `content for ${id}`),
      getMeta: vi.fn((id) => ({
        size: 10,
        path: id,
      })),
    };

    t.app.all("/**", (event) => {
      return serveStatic(event, serveStaticOptions);
    });
  });

  it("Uses custom getType function", async () => {
    const customOptions: ServeStaticOptions = {
      getContents: vi.fn(() => "content"),
      getMeta: vi.fn(() => ({ size: 10 })),
      getType: vi.fn((ext) => (ext === ".xyz" ? "application/custom" : undefined)),
    };

    t.app.all("/custom/**", (event) => {
      return serveStatic(event, customOptions);
    });

    const res = await t.fetch("/custom/file v2.xyz?query=123");
    expect(res.headers.get("content-type")).toBe("application/custom");
    expect(customOptions.getType).toHaveBeenCalledWith(".xyz");

    const res2 = await t.fetch("/custom/file.txt");
    expect(res2.headers.get("content-type")).toBe("text/plain");

    const res3 = await t.fetch("/custom/file");
    expect(res3.headers.get("content-type")).toBe(
      t.target === "web" ? null : "text/plain; charset=UTF-8",
    );
  });

  it("resolves the MIME type of an uppercase extension", async () => {
    const res = await t.fetch("/photos/IMG_0001.JPG");
    expect(res.headers.get("content-type")).toBe("image/jpeg");
  });

  it("uses the requested asset's MIME type for a precompressed variant", async () => {
    const files: Record<string, string> = {
      "/pre/app.js": "js",
      "/pre/app.js.gz": "js.gz",
      "/pre/app.js.br": "js.br",
      "/pre/style.css.gz": "css.gz",
      "/pre/docs/index.html.br": "html.br",
    };
    const options: ServeStaticOptions = {
      getContents: vi.fn((id) => files[id]),
      getMeta: vi.fn((id) => (files[id] ? { size: files[id].length } : undefined)),
      encodings: { gzip: ".gz", br: ".br" },
    };

    t.app.all("/pre/**", (event) => {
      return serveStatic(event, options);
    });

    for (const [path, acceptEncoding, body, type] of [
      ["/pre/app.js", "gzip", "js.gz", "text/javascript"],
      ["/pre/app.js", "br, gzip;q=0.5", "js.br", "text/javascript"],
      ["/pre/app.js", "identity", "js", "text/javascript"],
      ["/pre/style.css", "gzip", "css.gz", "text/css"],
      ["/pre/docs", "br", "html.br", "text/html"],
    ] as const) {
      const res = await t.fetch(path, { headers: { "accept-encoding": acceptEncoding } });
      expect(await res.text(), `${path} (${acceptEncoding})`).toBe(body);
      expect(res.headers.get("content-type"), `${path} (${acceptEncoding})`).toBe(type);
    }
  });

  it("does not overwrite a content-length already set on the response", async () => {
    // An explicit response content-length must win over the size derived from
    // meta — consistent with content-type / content-encoding / last-modified,
    // which are only set when not already present on the response.
    const options: ServeStaticOptions = {
      getContents: vi.fn(() => "content"),
      getMeta: vi.fn(() => ({ size: 18 })),
      headers: { "content-length": "999" },
    };

    t.app.all("/clen/**", (event) => {
      return serveStatic(event, options);
    });

    const res = await t.fetch("/clen/file.txt", { method: "HEAD" });
    expect(res.status).toBe(200);
    expect(res.headers.get("content-length")).toBe("999");
  });

  it("serves .wasm as application/wasm", async () => {
    // `WebAssembly.instantiateStreaming()` rejects any other type
    const res = await t.fetch("/module.wasm");
    expect(res.headers.get("content-type")).toBe("application/wasm");
  });
});

describe("serve static (malformed url)", () => {
  it("falls through on a malformed `%` instead of throwing", async () => {
    // With `allowMalformedURL`, a raw malformed `%` (e.g. `/foo%`) reaches
    // serveStatic and the final `decodeURI` would throw a URIError — a 500 that
    // bypasses `fallthrough`. The guarded decode falls back to the resolved id
    // so `fallthrough` (and 404 when off) are reached as normal.
    const options: ServeStaticOptions = {
      getContents: () => undefined,
      getMeta: () => undefined,
    };

    const fallthroughApp = new H3({ allowMalformedURL: true })
      .use((event) => serveStatic(event, { ...options, fallthrough: true }))
      .use(() => "next");
    const res = await fallthroughApp.request("/foo%");
    expect(res.status).toBe(200);
    expect(await res.text()).toBe("next");

    const notFoundApp = new H3({ allowMalformedURL: true }).all("/**", (event) =>
      serveStatic(event, options),
    );
    const res404 = await notFoundApp.request("/foo%");
    expect(res404.status).toBe(404);
  });

  it("never hands a raw backslash or bare `..` to the backend under allowMalformedURL", async () => {
    // Defense-in-depth guard for the trickiest input we could construct: a
    // malformed `%` (forcing the raw pathname) whose segment is popped by a
    // `..`, leaving single-encoded `%5c` separators. If the on-disk decode
    // (`%5c` → `\`) were not neutralized, the id would become
    // `/..\..\windows\win.ini` — a traversal above the root on backslash-aware
    // (e.g. Windows) filesystem backends. It is neutralized because serveStatic
    // re-resolves dot segments *after* that decode. The event layer cannot help
    // here: canonicalization never decodes a separator (and is skipped entirely
    // for a malformed path), so `%5c` reaches serveStatic in its wire form.
    let servedId: string | undefined;
    const app = new H3({ allowMalformedURL: true }).all("/**", (event) =>
      serveStatic(event, {
        getContents: (id) => {
          servedId = id;
          return `asset:${id}`;
        },
        getMeta: () => ({ size: 1 }),
      }),
    );

    const res = await app.request("/a%ZZ/../..%5c..%5cwindows%5cwin.ini");
    expect(res.status).toBe(200);
    expect(servedId).toBeDefined();
    expect(servedId).not.toContain("\\"); // no raw backslash separator
    expect(servedId).not.toMatch(/(^|[\\/])\.\.([\\/]|$)/); // no bare `..` segment
  });
});

describeMatrix("serve static range", (t, { it, expect }) => {
  const content = "0123456789".repeat(10);
  const mtime = 1_700_000_000_000;
  const lastModified = new Date(mtime).toUTCString();

  let getContents: ReturnType<typeof vi.fn>;
  let getMeta: ReturnType<typeof vi.fn>;

  beforeEach(() => {
    getContents = vi.fn((): any => content);
    getMeta = vi.fn((id: string) =>
      id.includes("404")
        ? undefined
        : {
            type: "text/plain",
            etag: '"v1"',
            mtime,
            size: id.endsWith(".gz") ? 40 : content.length,
          },
    );
    t.app.all("/**", (event) =>
      serveStatic(event, {
        getContents: getContents as ServeStaticOptions["getContents"],
        getMeta: getMeta as ServeStaticOptions["getMeta"],
        encodings: { gzip: ".gz" },
        headers: { "cache-control": "max-age=60" },
      }),
    );
  });

  const range = (value: string, extra: Record<string, string> = {}, method = "GET") =>
    t.fetch("/a.txt", { method, headers: { range: value, ...extra } });

  it("advertises accept-ranges on 200 (GET/HEAD) and 304", async () => {
    for (const method of ["GET", "HEAD"]) {
      const res = await t.fetch("/a.txt", { method });
      expect(res.status).toBe(200);
      expect(res.headers.get("accept-ranges")).toBe("bytes");
      expect(res.headers.get("content-length")).toBe("100");
    }
    const res = await t.fetch("/a.txt", { headers: { "if-none-match": '"v1"' } });
    expect(res.status).toBe(304);
    expect(res.headers.get("accept-ranges")).toBe("bytes");
  });

  for (const [header, cr, body] of [
    ["bytes=10-19", "10-19", content.slice(10, 20)],
    ["bytes=90-", "90-99", content.slice(90)],
    ["bytes=-10", "90-99", content.slice(90)],
    ["bytes=90-999", "90-99", content.slice(90)],
    ["bytes=-500", "0-99", content],
  ] as const) {
    it(`serves 206 for ${header}`, async () => {
      const res = await range(header);
      expect(res.status).toBe(206);
      expect(res.headers.get("content-range")).toBe(`bytes ${cr}/100`);
      expect(res.headers.get("content-length")).toBe(String(body.length));
      expect(res.headers.get("etag")).toBe('"v1"');
      expect(res.headers.get("last-modified")).toBe(lastModified);
      expect(res.headers.get("cache-control")).toBe("max-age=60");
      expect(res.headers.get("vary")).toBe("accept-encoding");
      expect(await res.text()).toBe(body);
    });
  }

  it("HEAD with range gives 206 headers without calling getContents", async () => {
    const get = await range("bytes=10-19");
    const head = await range("bytes=10-19", {}, "HEAD");
    expect(head.status).toBe(206);
    expect(head.headers.get("content-range")).toBe(get.headers.get("content-range"));
    expect(head.headers.get("content-length")).toBe("10");
    expect(await head.text()).toBe("");
    expect(getContents).toHaveBeenCalledTimes(1);
  });

  for (const header of ["bytes=100-", "bytes=150-200", "bytes=-0"]) {
    it(`416 for ${header} (GET/HEAD)`, async () => {
      for (const method of ["GET", "HEAD"]) {
        const res = await range(header, {}, method);
        expect(res.status).toBe(416);
        expect(res.headers.get("content-range")).toBe("bytes */100");
        expect(res.headers.get("content-length")).toBe("0");
        expect(await res.text()).toBe("");
      }
      expect(getContents).not.toHaveBeenCalled();
    });
  }

  for (const header of ["abc", "bytes=5-2", "bytes=", "items=0-1", "bytes=0-1,5-6"]) {
    it(`ignores invalid or multi-range ${header} (RFC 9110: 5-2 is invalid)`, async () => {
      const res = await range(header);
      expect(res.status).toBe(200);
      expect(res.headers.has("content-range")).toBe(false);
      expect(await res.text()).toBe(content);
    });
  }

  for (const size of [undefined, 0]) {
    it(`ignores range without known size (${size})`, async () => {
      getMeta.mockImplementation(() => ({ type: "text/plain", size }));
      const res = await range("bytes=0-9");
      expect(res.status).toBe(200);
      expect(res.headers.has("accept-ranges")).toBe(false);
      expect(await res.text()).toBe(content);
    });
  }

  it("if-range: strong etag match gives 206", async () => {
    expect((await range("bytes=0-9", { "if-range": '"v1"' })).status).toBe(206);
  });

  for (const ifRange of ['"v2"', 'W/"v1"', new Date(mtime - 1000).toUTCString(), "garbage"]) {
    it(`if-range ${ifRange} (strong comparison) gives full 200`, async () => {
      const res = await range("bytes=0-9", { "if-range": ifRange });
      expect(res.status).toBe(200);
      expect(await res.text()).toBe(content);
    });
  }

  it("if-range: exact date gives 206; if-range without range gives 200", async () => {
    expect((await range("bytes=0-9", { "if-range": lastModified })).status).toBe(206);
    const res = await t.fetch("/a.txt", { headers: { "if-range": '"v1"' } });
    expect(res.status).toBe(200);
  });

  it("304 is decided before range", async () => {
    const res = await range("bytes=0-9", { "if-none-match": '"v1"' });
    expect(res.status).toBe(304);
    expect(res.headers.has("content-range")).toBe(false);
  });

  it("slices the encoded variant using its own size", async () => {
    getContents.mockImplementation((id: string) => (id.endsWith(".gz") ? "g".repeat(40) : content));
    const res = await range("bytes=10-19", { "accept-encoding": "gzip" });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 10-19/40");
    expect(res.headers.get("vary")).toBe("accept-encoding");
    expect(res.headers.get("content-type")).toBe("text/plain");
    expect(await res.text()).toBe("g".repeat(10));

    const unsat = await range("bytes=40-", { "accept-encoding": "gzip" });
    expect(unsat.status).toBe(416);
    expect(unsat.headers.has("content-encoding")).toBe(false);
  });

  it("404/405 carry no range headers", async () => {
    const notFound = await t.fetch("/404.txt", { headers: { range: "bytes=0-9" } });
    expect(notFound.status).toBe(404);
    expect(notFound.headers.has("accept-ranges")).toBe(false);
    expect(notFound.headers.has("content-range")).toBe(false);

    const post = await t.fetch("/a.txt", { method: "POST", headers: { range: "bytes=0-9" } });
    expect(post.status).toBe(405);
    expect(post.headers.has("accept-ranges")).toBe(false);
    expect(post.headers.has("content-range")).toBe(false);
  });

  it("range content-length wins over user header; user header kept without range", async () => {
    const app = new H3().all("/**", (event) =>
      serveStatic(event, {
        getContents: getContents as ServeStaticOptions["getContents"],
        getMeta: getMeta as ServeStaticOptions["getMeta"],
        headers: { "content-length": "999" },
      }),
    );
    const partial = await app.request("/a.txt", { headers: { range: "bytes=0-9" } });
    expect(partial.headers.get("content-length")).toBe("10");
    await partial.arrayBuffer();
    const full = await app.request("/a.txt", { method: "HEAD" });
    expect(full.headers.get("content-length")).toBe("999");
  });

  const bodies: [string, () => BodyInit][] = [
    ["string", () => content],
    ["Blob", () => new Blob([content])],
    ["Uint8Array", () => new TextEncoder().encode(content)],
    ["ArrayBuffer", () => new TextEncoder().encode(content).buffer as ArrayBuffer],
    [
      "ReadableStream",
      () =>
        new ReadableStream({
          start(c) {
            const bytes = new TextEncoder().encode(content);
            c.enqueue(bytes.subarray(0, 15));
            c.enqueue(bytes.subarray(15, 60));
            c.enqueue(bytes.subarray(60));
            c.close();
          },
        }),
    ],
  ];

  for (const [name, make] of bodies) {
    it(`slices ${name} bodies`, async () => {
      getContents.mockImplementation(make);
      const res = await range("bytes=12-71");
      expect(res.status).toBe(206);
      expect(await res.text()).toBe(content.slice(12, 72));
    });
  }

  it("empty contents with range falls back to empty 200", async () => {
    getContents.mockImplementation(() => undefined);
    const res = await range("bytes=0-9");
    expect(res.status).toBe(200);
    expect(res.headers.has("content-range")).toBe(false);
    expect(await res.text()).toBe("");
  });
});

import { beforeEach, describe, it, expect, vi } from "vitest";
import { H3, serveStatic, type ServeStaticOptions } from "../src/index.ts";
import { describeMatrix } from "./_setup.ts";

describeMatrix("serve static", (t, { it, expect }) => {
  beforeEach(() => {
    const serveStaticOptions: ServeStaticOptions = {
      getContents: vi.fn((id) => (id.includes("404") ? undefined : `asset:${id}`)),
      getMeta: vi.fn((id) =>
        id.includes("404")
          ? undefined
          : {
              type: "text/plain",
              encoding: "utf8",
              etag: "w/123",
              mtime: 1_700_000_000_000,
              path: id,
              size: `asset:${id}`.length,
            },
      ),
      indexNames: ["/index.html"],
      encodings: { gzip: ".gz", br: ".br" },
      headers: {
        "cache-control": "public, max-age=86400",
      },
    };

    t.app.all("/**", (event) => {
      return serveStatic(event, serveStaticOptions);
    });
  });

  const expectedHeaders = {
    "content-type": "text/plain",
    etag: "w/123",
    "content-encoding": "utf8",
    "last-modified": new Date(1_700_000_000_000).toUTCString(),
    vary: "accept-encoding",
    "cache-control": "public, max-age=86400",
  };

  it("Can serve asset (GET)", async () => {
    const res = await t.fetch("/test.png", {
      headers: {
        "if-none-match": "w/456",
        "if-modified-since": new Date(1_700_000_000_000 - 1).toUTCString(),
        "accept-encoding": "gzip, br",
      },
    });

    expect(res.status).toEqual(200);
    expect(await res.text()).toBe("asset:/test.png.gz");
    expect(Object.fromEntries(res.headers)).toMatchObject(expectedHeaders);
    expect(res.headers.get("content-length")).toBe("18");
  });

  it("Can serve asset (HEAD)", async () => {
    const headRes = await t.fetch("/test.png", {
      method: "HEAD",
      headers: {
        "if-none-match": "w/456",
        "if-modified-since": new Date(1_700_000_000_000 - 1).toUTCString(),
        "accept-encoding": "gzip, br",
      },
    });

    expect(headRes.status).toEqual(200);
    expect(await headRes.text()).toBe("");
    expect(Object.fromEntries(headRes.headers)).toMatchObject(expectedHeaders);
    expect(headRes.headers.get("content-length")).toBe("18");
  });

  it("Sets vary when a single encoding is accepted", async () => {
    const res = await t.fetch("/test.png", {
      headers: { "accept-encoding": "gzip" },
    });
    expect(await res.text()).toBe("asset:/test.png.gz");
    expect(res.headers.get("vary")).toBe("accept-encoding");
  });

  it("Keeps existing vary values", async () => {
    t.app.all("/cors/**", (event) => {
      event.res.headers.set("vary", "origin");
      return serveStatic(event, {
        getContents: (id) => `asset:${id}`,
        getMeta: (id) => ({ type: "text/plain", path: id }),
        encodings: { gzip: ".gz" },
      });
    });
    const res = await t.fetch("/cors/test.png", {
      headers: { "accept-encoding": "gzip" },
    });
    expect(res.headers.get("vary")).toBe("origin, accept-encoding");
  });

  it("Sets vary when no encoding is accepted", async () => {
    // Explicit `identity`: node's fetch adds `accept-encoding: gzip, deflate` when unset.
    const res = await t.fetch("/test.png", {
      headers: { "accept-encoding": "identity" },
    });
    expect(await res.text()).toBe("asset:/test.png");
    expect(res.headers.get("vary")).toBe("accept-encoding");
  });

  it("Does not set vary without configured encodings", async () => {
    t.app.all("/plain/**", (event) => {
      return serveStatic(event, {
        getContents: (id) => `asset:${id}`,
        getMeta: (id) => ({ type: "text/plain", path: id }),
      });
    });
    const res = await t.fetch("/plain/test.png", {
      headers: { "accept-encoding": "gzip" },
    });
    expect(res.headers.get("vary")).toBeNull();
  });

  it("Does not duplicate vary values", async () => {
    for (const [i, vary] of ["Accept-Encoding", "origin,accept-encoding", "*"].entries()) {
      t.app.all(`/dedupe${i}/**`, (event) => {
        event.res.headers.set("vary", vary);
        return serveStatic(event, {
          getContents: (id) => `asset:${id}`,
          getMeta: (id) => ({ type: "text/plain", path: id }),
          encodings: { gzip: ".gz" },
        });
      });
      const res = await t.fetch(`/dedupe${i}/test.png`, {
        headers: { "accept-encoding": "gzip" },
      });
      expect(res.headers.get("vary")).toBe(vary);
    }
  });

  it("Matches encodings with q-values and any case", async () => {
    for (const [acceptEncoding, expected] of [
      ["gzip;q=1.0", "asset:/test.png.gz"],
      ["GZIP", "asset:/test.png.gz"],
      ["br ; q=1", "asset:/test.png.br"],
      // Preferred by weight, not by header order.
      ["gzip;q=0.5, br;q=0.8", "asset:/test.png.br"],
      // Equal weights keep header order.
      ["br, gzip", "asset:/test.png.br"],
      // `q=0` means "not acceptable".
      ["gzip;q=0, br;q=0.000", "asset:/test.png"],
      ["gzip;q=0", "asset:/test.png"],
      // A coding with an unparsable weight is dropped (identity is always safe).
      ["gzip;q=0invalid, br;q=0.5", "asset:/test.png.br"],
      ["gzip;q=0.0001", "asset:/test.png"],
      ["gzip;q=-1", "asset:/test.png"],
      ['gzip;q="0"', "asset:/test.png"],
      ["br;q=0.001, gzip;q=0.0010", "asset:/test.png.br"],
      // `x-gzip` is an alias of `gzip`.
      ["X-GZIP", "asset:/test.png.gz"],
      // `*` matches any coding not listed explicitly.
      ["*", "asset:/test.png.gz"],
      ["gzip;q=0, *", "asset:/test.png.br"],
      ["br;q=0.5, *;q=0.8", "asset:/test.png.gz"],
      ["*;q=0", "asset:/test.png"],
      // Explicitly listed codings win ties with `*` matches.
      ["*, br", "asset:/test.png.br"],
      // The first occurrence of a coding wins.
      ["gzip;q=0, gzip", "asset:/test.png"],
    ]) {
      const res = await t.fetch("/test.png", {
        headers: { "accept-encoding": acceptEncoding! },
      });
      expect(await res.text(), acceptEncoding).toBe(expected);
    }
  });

  it("Ignores inherited object keys in accept-encoding", async () => {
    const res = await t.fetch("/test.png", {
      headers: { "accept-encoding": "constructor, __proto__, toString" },
    });
    expect(await res.text()).toBe("asset:/test.png");
  });

  it("Normalizes configured encoding names", async () => {
    t.app.all("/aliases/**", (event) => {
      return serveStatic(event, {
        getContents: (id) => `asset:${id}`,
        getMeta: (id) => ({ type: "text/plain", path: id }),
        encodings: { GZIP: ".gz", "x-compress": ".Z" },
      });
    });
    for (const [acceptEncoding, expected] of [
      ["gzip", "asset:/aliases/test.png.gz"],
      ["compress", "asset:/aliases/test.png.Z"],
      ["x-compress", "asset:/aliases/test.png.Z"],
    ]) {
      const res = await t.fetch("/aliases/test.png", {
        headers: { "accept-encoding": acceptEncoding! },
      });
      expect(await res.text(), acceptEncoding).toBe(expected);
    }
  });

  it("Handles cache (if-none-match)", async () => {
    const res = await t.fetch("/test.png", {
      headers: { "if-none-match": "w/123" },
    });
    expect(res.headers.get("vary")).toBe("accept-encoding");
    expect(res.headers.get("etag")).toBe(expectedHeaders.etag);
    expect(res.status).toEqual(304);
    expect(await res.text()).toBe("");
  });

  it("Handles cache (if-modified-since)", async () => {
    const res = await t.fetch("/test.png", {
      headers: {
        "if-modified-since": new Date(1_700_000_000_001).toUTCString(),
      },
    });
    expect(res.status).toEqual(304);
    expect(await res.text()).toBe("");
  });

  it("Returns 404 if not found", async () => {
    const res = await t.fetch("/404/test.png");
    expect(res.status).toEqual(404);

    const headRes = await t.fetch("/404/test.png", { method: "HEAD" });
    expect(headRes.status).toEqual(404);
  });

  it("Handles cache (if-modified-since) for sub-second mtime", async () => {
    // mtime with millisecond precision. The `last-modified` header the server
    // emits is truncated to whole seconds (HTTP-date granularity), so a client
    // echoing that exact value in `if-modified-since` must still get a 304.
    const subSecondOptions: ServeStaticOptions = {
      getContents: vi.fn((id) => `asset:${id}`),
      getMeta: vi.fn((id) => ({
        type: "text/plain",
        mtime: 1_700_000_000_500, // 500ms past the whole second
        path: id,
        size: `asset:${id}`.length,
      })),
    };
    t.app.all("/subsec/**", (event) => serveStatic(event, subSecondOptions));

    // The exact value the server reports in `last-modified`.
    const lastModified = new Date(1_700_000_000_500).toUTCString();
    const res = await t.fetch("/subsec/test.png", {
      headers: { "if-modified-since": lastModified },
    });
    expect(res.status).toEqual(304);
    expect(await res.text()).toBe("");
  });

  it("Returns 405 if other methods used", async () => {
    const res = await t.fetch("/test.png", { method: "POST" });
    expect(res.status).toEqual(405);
  });

  it("Prevents path traversal via encoded dot segments", async () => {
    const res = await t.fetch("/%2e%2e/%2e%2e/etc/passwd");
    expect(res.status).toEqual(200);
    const text = await res.text();
    // After resolving dot segments, `/../../../etc/passwd` becomes `/etc/passwd`
    // The id must NOT contain `..` traversal sequences
    expect(text).not.toContain("..");
    expect(text).toMatch(/^asset:\/etc\/passwd/);
  });

  it("blocks path traversal attempts", async () => {
    const blocked = [
      "/../etc/passwd",
      "/%2e%2e/",
      "/%2E%2E/",
      "/assets/../../etc/passwd",
      "/assets/..",
      "/..\\etc\\passwd",
      "/..%5c..%5cetc%5cpasswd",
      "/..%2f..%2fetc%2fpasswd",
      "/..",
    ];
    for (const path of blocked) {
      const res = await t.fetch(path);
      const text = await res.text();
      // No bare `..` *segment*. Asserted on segment boundaries rather than as a
      // substring: an encoded separator stays encoded, so `/..%5c..%5cetc` (like
      // its `%2f` sibling) reaches the backend as one opaque segment whose text
      // begins with `..` but which has no boundary for a `..` to traverse across.
      // Decoding it into a real `/` is what this test exists to prevent.
      expect(text).not.toMatch(/(^|[\\/])\.\.([\\/]|$)/);
    }
  });

  it("does not pass double-encoded dot segments as traversal to backend", async () => {
    const res = await t.fetch("/%252e%252e/%252e%252e/etc/passwd");
    const text = await res.text();
    // After first decode: %2e%2e/%2e%2e/etc/passwd
    // Backend must NOT see %2e%2e which could be resolved as .. by downstream
    expect(text).not.toContain("%2e%2e");
    expect(text).not.toContain("%2E%2E");
  });

  it("does not reintroduce a backslash separator when decoding the id", async () => {
    // A double-encoded backslash traversal exercises the final `decodeURI`:
    // `%255c` survives `resolveDotSegments` (a single `%5c` is decoded to `\`
    // and normalized away one layer earlier), and the decode must collapse it
    // to a *literal* `%5c` — never a raw `\`. So the whole thing stays one
    // opaque segment: the `..` never becomes a bare path segment, and no new
    // separator boundary is introduced.
    const res = await t.fetch("/..%255c..%255cetc%255cpasswd");
    const text = await res.text();
    expect(text).not.toContain("\\"); // no raw backslash separator
    expect(text).toContain("%5c"); // stayed literal, not decoded to `\`
    // no bare `..` segment — boundaries include `\` so a decoded backslash
    // separator would be caught too, not only a `/`.
    expect(text).not.toMatch(/(^|[\\/])\.\.([\\/]|$)/);
  });

  it("keeps a single-encoded backslash opaque in the id", async () => {
    // `decodeURI` decodes `%5c` (not RFC 3986 reserved) to a raw `\`, which
    // `resolveDotSegments` then normalizes to `/`. That would hand the backend a
    // segment boundary that never existed for routing: `event.url.pathname` keeps
    // `%5c` encoded, so rou3 — and every `use(route, ...)` guard — sees one opaque
    // segment. The id must keep the same shape as what matched.
    const res = await t.fetch("/foo%5cbar.txt");
    const text = await res.text();
    expect(text).not.toContain("\\"); // never a raw backslash
    expect(text).not.toContain("/foo/bar.txt"); // and never a real boundary
    expect(text).toContain("%5c");
  });

  it("does not let an encoded backslash skip a pathname-scoped guard", async () => {
    // The desync in full: a `use("/private/**")` guard is matched against
    // `event.url.pathname` (`/private%5csecret.txt` — one segment, no match),
    // while the id must not resolve to the guarded `/private/secret.txt`.
    let guarded = false;
    const app = new H3()
      .use("/private/**", () => {
        guarded = true;
        return new Response("denied", { status: 401 });
      })
      .all("/**", (event) =>
        serveStatic(event, {
          getMeta: (id) => (id === "/private/secret.txt" ? { size: 6 } : undefined),
          getContents: () => "SECRET",
        }),
      );

    // Sanity: the guard does cover the canonical spelling.
    expect((await app.request("/private/secret.txt")).status).toBe(401);
    expect(guarded).toBe(true);

    const res = await app.request("/private%5csecret.txt");
    expect(res.status).toBe(404); // not 200 "SECRET"
    expect(await res.text()).not.toContain("SECRET");
  });

  it("decodes an encoded separator for the on-disk lookup", async () => {
    // serveStatic resolves `.`/`..` traversal first, then decodes once more, so
    // the id reaches the backend fully decoded — matching `sirv`/`serve-static`
    // and letting a filesystem-backed `getContents` skip self-decoding.
    // `/files/a%252fb` → id `a%2fb` (the encoded slash stays a literal `%2f`
    // segment, so no traversal is reintroduced).
    const res = await t.fetch("/files/a%252fb");
    expect(res.status).toEqual(200);
    const text = await res.text();
    expect(text).toContain("a%2fb");
    expect(text).not.toContain("a%252fb");
  });

  it("decodes a literal `%` in a filename for the on-disk lookup", async () => {
    // A file whose name contains a literal `%` (`50%.png`) is requested as
    // `/50%25.png`. The event layer preserves `%25`, then serveStatic decodes it
    // once more so the id reaches the backend as `/50%.png` — the on-disk name —
    // aligning with `sirv`/`serve-static` instead of forcing self-decoding.
    const res = await t.fetch("/50%25.png");
    expect(res.status).toEqual(200);
    const text = await res.text();
    expect(text).toContain("/50%.png");
    expect(text).not.toContain("/50%25.png");
  });

  it("allows legitimate paths with dots", async () => {
    const allowed = [
      "/_...grid_123.js",
      "/file..name.js",
      "/.hidden",
      "/assets/file.txt",
      "/...test/file.js",
    ];
    for (const path of allowed) {
      const res = await t.fetch(path);
      expect(res.status).toEqual(200);
      const text = await res.text();
      expect(text).toContain("asset:");
    }
  });
});

describeMatrix("serve static with fallthrough", (t, { it, expect }) => {
  beforeEach(() => {
    const serveStaticOptions = {
      getContents: vi.fn((id) => {
        return id.includes("404") || id.includes("fallthrough") ? undefined : `asset:${id}`;
      }),
      getMeta: vi.fn((id) =>
        id.includes("404") || id.includes("fallthrough")
          ? undefined
          : {
              type: "text/plain",
              encoding: "utf8",
              etag: "w/123",
              mtime: 1_700_000_000_000,
              path: id,
              size: `asset:${id}`.length,
            },
      ),
      indexNames: ["/index.html"],
      encodings: { gzip: ".gz", br: ".br" },
      fallthrough: true,
    } satisfies ServeStaticOptions;

    t.app.use((event) => {
      return serveStatic(event, serveStaticOptions);
    });

    t.app.use((event) => {
      if (event.path.includes("404")) {
        event.res.status = 404;
      }
      return { fallthroughTest: "passing" };
    });
  });

  const expectedHeaders = {
    "content-type": "text/plain",
    etag: "w/123",
    "content-encoding": "utf8",
    "last-modified": new Date(1_700_000_000_000).toUTCString(),
    vary: "accept-encoding",
  };

  it("Can serve asset (GET)", async () => {
    const res = await t.fetch("/test.png", {
      headers: {
        "if-none-match": "w/456",
        "if-modified-since": new Date(1_700_000_000_000 - 1).toUTCString(),
        "accept-encoding": "gzip, br",
      },
    });

    expect(res.status).toEqual(200);
    expect(await res.text()).toBe("asset:/test.png.gz");
    expect(Object.fromEntries(res.headers)).toMatchObject(expectedHeaders);
    expect(res.headers.get("content-length")).toBe("18");
  });

  it("Can serve asset (HEAD)", async () => {
    const headRes = await t.fetch("/test.png", {
      method: "HEAD",
      headers: {
        "if-none-match": "w/456",
        "if-modified-since": new Date(1_700_000_000_000 - 1).toUTCString(),
        "accept-encoding": "gzip, br",
      },
    });

    expect(headRes.status).toEqual(200);
    expect(await headRes.text()).toBe("");
    expect(Object.fromEntries(headRes.headers)).toMatchObject(expectedHeaders);
    expect(headRes.headers.get("content-length")).toBe("18");
  });

  it("Handles cache (if-none-match)", async () => {
    const res = await t.fetch("/test.png", {
      headers: { "if-none-match": "w/123" },
    });
    expect(res.headers.get("etag")).toBe(expectedHeaders.etag);
    expect(res.status).toEqual(304);
    expect(await res.text()).toBe("");
  });

  it("Handles cache (if-modified-since)", async () => {
    const res = await t.fetch("/test.png", {
      headers: {
        "if-modified-since": new Date(1_700_000_000_001).toUTCString(),
      },
    });
    expect(res.status).toEqual(304);
    expect(await res.text()).toBe("");
  });

  it("Returns 404 if not found", async () => {
    const res = await t.fetch("/404/test.png");
    expect(res.status).toEqual(404);

    const headRes = await t.fetch("/404/test.png", { method: "HEAD" });
    expect(headRes.status).toEqual(404);
  });

  it("ignores if-modified-since when a non-matching if-none-match is present (RFC 9110 §13.1.3, #1454)", async () => {
    // If-None-Match takes precedence: it does not match, so a fresh 200 must be
    // returned even though If-Modified-Since alone would have produced a 304.
    const res = await t.fetch("/test.png", {
      headers: {
        "if-none-match": "w/999",
        "if-modified-since": new Date(1_700_000_000_001).toUTCString(),
      },
    });
    expect(res.status).toEqual(200);
    expect(await res.text()).toContain("asset:/test.png");
  });

  it("Falls through to the next handler", async () => {
    const res = await t.fetch("/fallthrough/test.png");
    expect(res.status).toEqual(200);
    expect(await res.json()).toEqual({ fallthroughTest: "passing" });
  });

  it("Does not leak vary to the next handler", async () => {
    const res = await t.fetch("/fallthrough/test.png", {
      headers: { "accept-encoding": "gzip" },
    });
    expect(await res.json()).toEqual({ fallthroughTest: "passing" });
    expect(res.headers.get("vary")).toBeNull();
  });
});

describeMatrix("serve static MIME types", (t, { it, expect }) => {
  beforeEach(() => {
    const serveStaticOptions: ServeStaticOptions = {
      getContents: vi.fn((id) => `content for ${id}`),
      getMeta: vi.fn((id) => ({
        size: 10,
        path: id,
      })),
    };

    t.app.all("/**", (event) => {
      return serveStatic(event, serveStaticOptions);
    });
  });

  it("Uses custom getType function", async () => {
    const customOptions: ServeStaticOptions = {
      getContents: vi.fn(() => "content"),
      getMeta: vi.fn(() => ({ size: 10 })),
      getType: vi.fn((ext) => (ext === ".xyz" ? "application/custom" : undefined)),
    };

    t.app.all("/custom/**", (event) => {
      return serveStatic(event, customOptions);
    });

    const res = await t.fetch("/custom/file v2.xyz?query=123");
    expect(res.headers.get("content-type")).toBe("application/custom");
    expect(customOptions.getType).toHaveBeenCalledWith(".xyz");

    const res2 = await t.fetch("/custom/file.txt");
    expect(res2.headers.get("content-type")).toBe("text/plain");

    const res3 = await t.fetch("/custom/file");
    expect(res3.headers.get("content-type")).toBe(
      t.target === "web" ? null : "text/plain; charset=UTF-8",
    );
  });

  it("resolves the MIME type of an uppercase extension", async () => {
    const res = await t.fetch("/photos/IMG_0001.JPG");
    expect(res.headers.get("content-type")).toBe("image/jpeg");
  });

  it("uses the requested asset's MIME type for a precompressed variant", async () => {
    const files: Record<string, string> = {
      "/pre/app.js": "js",
      "/pre/app.js.gz": "js.gz",
      "/pre/app.js.br": "js.br",
      "/pre/style.css.gz": "css.gz",
      "/pre/docs/index.html.br": "html.br",
    };
    const options: ServeStaticOptions = {
      getContents: vi.fn((id) => files[id]),
      getMeta: vi.fn((id) => (files[id] ? { size: files[id].length } : undefined)),
      encodings: { gzip: ".gz", br: ".br" },
    };

    t.app.all("/pre/**", (event) => {
      return serveStatic(event, options);
    });

    for (const [path, acceptEncoding, body, type] of [
      ["/pre/app.js", "gzip", "js.gz", "text/javascript"],
      ["/pre/app.js", "br, gzip;q=0.5", "js.br", "text/javascript"],
      ["/pre/app.js", "identity", "js", "text/javascript"],
      ["/pre/style.css", "gzip", "css.gz", "text/css"],
      ["/pre/docs", "br", "html.br", "text/html"],
    ] as const) {
      const res = await t.fetch(path, { headers: { "accept-encoding": acceptEncoding } });
      expect(await res.text(), `${path} (${acceptEncoding})`).toBe(body);
      expect(res.headers.get("content-type"), `${path} (${acceptEncoding})`).toBe(type);
    }
  });

  it("does not overwrite a content-length already set on the response", async () => {
    // An explicit response content-length must win over the size derived from
    // meta — consistent with content-type / content-encoding / last-modified,
    // which are only set when not already present on the response.
    const options: ServeStaticOptions = {
      getContents: vi.fn(() => "content"),
      getMeta: vi.fn(() => ({ size: 18 })),
      headers: { "content-length": "999" },
    };

    t.app.all("/clen/**", (event) => {
      return serveStatic(event, options);
    });

    const res = await t.fetch("/clen/file.txt", { method: "HEAD" });
    expect(res.status).toBe(200);
    expect(res.headers.get("content-length")).toBe("999");
  });

  it("serves .wasm as application/wasm", async () => {
    // `WebAssembly.instantiateStreaming()` rejects any other type
    const res = await t.fetch("/module.wasm");
    expect(res.headers.get("content-type")).toBe("application/wasm");
  });
});

describe("serve static (malformed url)", () => {
  it("falls through on a malformed `%` instead of throwing", async () => {
    // With `allowMalformedURL`, a raw malformed `%` (e.g. `/foo%`) reaches
    // serveStatic and the final `decodeURI` would throw a URIError — a 500 that
    // bypasses `fallthrough`. The guarded decode falls back to the resolved id
    // so `fallthrough` (and 404 when off) are reached as normal.
    const options: ServeStaticOptions = {
      getContents: () => undefined,
      getMeta: () => undefined,
    };

    const fallthroughApp = new H3({ allowMalformedURL: true })
      .use((event) => serveStatic(event, { ...options, fallthrough: true }))
      .use(() => "next");
    const res = await fallthroughApp.request("/foo%");
    expect(res.status).toBe(200);
    expect(await res.text()).toBe("next");

    const notFoundApp = new H3({ allowMalformedURL: true }).all("/**", (event) =>
      serveStatic(event, options),
    );
    const res404 = await notFoundApp.request("/foo%");
    expect(res404.status).toBe(404);
  });

  it("never hands a raw backslash or bare `..` to the backend under allowMalformedURL", async () => {
    // Defense-in-depth guard for the trickiest input we could construct: a
    // malformed `%` (forcing the raw pathname) whose segment is popped by a
    // `..`, leaving single-encoded `%5c` separators. If the on-disk decode
    // (`%5c` → `\`) were not neutralized, the id would become
    // `/..\..\windows\win.ini` — a traversal above the root on backslash-aware
    // (e.g. Windows) filesystem backends. It is neutralized because serveStatic
    // re-resolves dot segments *after* that decode. The event layer cannot help
    // here: canonicalization never decodes a separator (and is skipped entirely
    // for a malformed path), so `%5c` reaches serveStatic in its wire form.
    let servedId: string | undefined;
    const app = new H3({ allowMalformedURL: true }).all("/**", (event) =>
      serveStatic(event, {
        getContents: (id) => {
          servedId = id;
          return `asset:${id}`;
        },
        getMeta: () => ({ size: 1 }),
      }),
    );

    const res = await app.request("/a%ZZ/../..%5c..%5cwindows%5cwin.ini");
    expect(res.status).toBe(200);
    expect(servedId).toBeDefined();
    expect(servedId).not.toContain("\\"); // no raw backslash separator
    expect(servedId).not.toMatch(/(^|[\\/])\.\.([\\/]|$)/); // no bare `..` segment
  });
});

describeMatrix("serve static range", (t, { it, expect }) => {
  const content = "0123456789".repeat(10);
  const mtime = 1_700_000_000_000;
  const lastModified = new Date(mtime).toUTCString();

  let getContents: ReturnType<typeof vi.fn>;
  let getMeta: ReturnType<typeof vi.fn>;

  beforeEach(() => {
    getContents = vi.fn((): any => content);
    getMeta = vi.fn((id: string) =>
      id.includes("404")
        ? undefined
        : {
            type: "text/plain",
            etag: '"v1"',
            mtime,
            size: id.endsWith(".gz") ? 40 : content.length,
          },
    );
    t.app.all("/**", (event) =>
      serveStatic(event, {
        getContents: getContents as ServeStaticOptions["getContents"],
        getMeta: getMeta as ServeStaticOptions["getMeta"],
        encodings: { gzip: ".gz" },
        headers: { "cache-control": "max-age=60" },
      }),
    );
  });

  const range = (value: string, extra: Record<string, string> = {}, method = "GET") =>
    t.fetch("/a.txt", { method, headers: { range: value, ...extra } });

  it("advertises accept-ranges on 200 (GET/HEAD) and 304", async () => {
    for (const method of ["GET", "HEAD"]) {
      // node's fetch would otherwise negotiate the `.gz` variant
      const res = await t.fetch("/a.txt", { method, headers: { "accept-encoding": "identity" } });
      expect(res.status).toBe(200);
      expect(res.headers.get("accept-ranges")).toBe("bytes");
      expect(res.headers.get("content-length")).toBe("100");
    }
    const res = await t.fetch("/a.txt", { headers: { "if-none-match": '"v1"' } });
    expect(res.status).toBe(304);
    expect(res.headers.get("accept-ranges")).toBe("bytes");
  });

  for (const [header, cr, body] of [
    ["bytes=10-19", "10-19", content.slice(10, 20)],
    ["bytes=90-", "90-99", content.slice(90)],
    ["bytes=-10", "90-99", content.slice(90)],
    ["bytes=90-999", "90-99", content.slice(90)],
    ["bytes=-500", "0-99", content],
  ] as const) {
    it(`serves 206 for ${header}`, async () => {
      const res = await range(header);
      expect(res.status).toBe(206);
      expect(res.headers.get("content-range")).toBe(`bytes ${cr}/100`);
      expect(res.headers.get("content-length")).toBe(String(body.length));
      expect(res.headers.get("etag")).toBe('"v1"');
      expect(res.headers.get("last-modified")).toBe(lastModified);
      expect(res.headers.get("cache-control")).toBe("max-age=60");
      expect(res.headers.get("vary")).toBe("accept-encoding");
      expect(await res.text()).toBe(body);
    });
  }

  it("HEAD with range gives 206 headers without calling getContents", async () => {
    const get = await range("bytes=10-19");
    const head = await range("bytes=10-19", {}, "HEAD");
    expect(head.status).toBe(206);
    expect(head.headers.get("content-range")).toBe(get.headers.get("content-range"));
    expect(head.headers.get("content-length")).toBe("10");
    expect(await head.text()).toBe("");
    expect(getContents).toHaveBeenCalledTimes(1);
  });

  for (const header of ["bytes=100-", "bytes=150-200", "bytes=-0"]) {
    it(`416 for ${header} (GET/HEAD)`, async () => {
      for (const method of ["GET", "HEAD"]) {
        const res = await range(header, {}, method);
        expect(res.status).toBe(416);
        expect(res.headers.get("content-range")).toBe("bytes */100");
        expect(res.headers.get("content-length")).toBe("0");
        expect(await res.text()).toBe("");
      }
      expect(getContents).not.toHaveBeenCalled();
    });
  }

  for (const header of ["abc", "bytes=5-2", "bytes=", "items=0-1", "bytes=0-1,5-6"]) {
    it(`ignores invalid or multi-range ${header} (RFC 9110: 5-2 is invalid)`, async () => {
      const res = await range(header);
      expect(res.status).toBe(200);
      expect(res.headers.has("content-range")).toBe(false);
      expect(await res.text()).toBe(content);
    });
  }

  for (const size of [undefined, 0]) {
    it(`ignores range without known size (${size})`, async () => {
      getMeta.mockImplementation(() => ({ type: "text/plain", size }));
      const res = await range("bytes=0-9");
      expect(res.status).toBe(200);
      expect(res.headers.has("accept-ranges")).toBe(false);
      expect(await res.text()).toBe(content);
    });
  }

  it("if-range: strong etag match gives 206", async () => {
    expect((await range("bytes=0-9", { "if-range": '"v1"' })).status).toBe(206);
  });

  for (const ifRange of ['"v2"', 'W/"v1"', new Date(mtime - 1000).toUTCString(), "garbage"]) {
    it(`if-range ${ifRange} (strong comparison) gives full 200`, async () => {
      const res = await range("bytes=0-9", { "if-range": ifRange });
      expect(res.status).toBe(200);
      expect(await res.text()).toBe(content);
    });
  }

  it("if-range: exact date gives 206; if-range without range gives 200", async () => {
    expect((await range("bytes=0-9", { "if-range": lastModified })).status).toBe(206);
    const res = await t.fetch("/a.txt", { headers: { "if-range": '"v1"' } });
    expect(res.status).toBe(200);
  });

  it("304 is decided before range", async () => {
    const res = await range("bytes=0-9", { "if-none-match": '"v1"' });
    expect(res.status).toBe(304);
    expect(res.headers.has("content-range")).toBe(false);
  });

  it("slices the encoded variant using its own size", async () => {
    getContents.mockImplementation((id: string) => (id.endsWith(".gz") ? "g".repeat(40) : content));
    const res = await range("bytes=10-19", { "accept-encoding": "gzip" });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 10-19/40");
    expect(res.headers.get("vary")).toBe("accept-encoding");
    expect(res.headers.get("content-type")).toBe("text/plain");
    expect(await res.text()).toBe("g".repeat(10));

    const unsat = await range("bytes=40-", { "accept-encoding": "gzip" });
    expect(unsat.status).toBe(416);
    expect(unsat.headers.has("content-encoding")).toBe(false);
  });

  it("404/405 carry no range headers", async () => {
    const notFound = await t.fetch("/404.txt", { headers: { range: "bytes=0-9" } });
    expect(notFound.status).toBe(404);
    expect(notFound.headers.has("accept-ranges")).toBe(false);
    expect(notFound.headers.has("content-range")).toBe(false);

    const post = await t.fetch("/a.txt", { method: "POST", headers: { range: "bytes=0-9" } });
    expect(post.status).toBe(405);
    expect(post.headers.has("accept-ranges")).toBe(false);
    expect(post.headers.has("content-range")).toBe(false);
  });

  it("range content-length wins over user header; user header kept without range", async () => {
    const app = new H3().all("/**", (event) =>
      serveStatic(event, {
        getContents: getContents as ServeStaticOptions["getContents"],
        getMeta: getMeta as ServeStaticOptions["getMeta"],
        headers: { "content-length": "999" },
      }),
    );
    const partial = await app.request("/a.txt", { headers: { range: "bytes=0-9" } });
    expect(partial.headers.get("content-length")).toBe("10");
    await partial.arrayBuffer();
    const full = await app.request("/a.txt", { method: "HEAD" });
    expect(full.headers.get("content-length")).toBe("999");
  });

  const bodies: [string, () => BodyInit][] = [
    ["string", () => content],
    ["Blob", () => new Blob([content])],
    ["Uint8Array", () => new TextEncoder().encode(content)],
    ["ArrayBuffer", () => new TextEncoder().encode(content).buffer as ArrayBuffer],
    [
      "ReadableStream",
      () =>
        new ReadableStream({
          start(c) {
            const bytes = new TextEncoder().encode(content);
            c.enqueue(bytes.subarray(0, 15));
            c.enqueue(bytes.subarray(15, 60));
            c.enqueue(bytes.subarray(60));
            c.close();
          },
        }),
    ],
  ];

  for (const [name, make] of bodies) {
    it(`slices ${name} bodies`, async () => {
      getContents.mockImplementation(make);
      const res = await range("bytes=12-71");
      expect(res.status).toBe(206);
      expect(await res.text()).toBe(content.slice(12, 72));
    });
  }

  it("empty contents with range falls back to empty 200", async () => {
    getContents.mockImplementation(() => undefined);
    const res = await range("bytes=0-9");
    expect(res.status).toBe(200);
    expect(res.headers.has("content-range")).toBe(false);
    expect(await res.text()).toBe("");
  });
});

